<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { CheckCircle2, Clipboard, KeyRound, LogOut } from '@lucide/vue'
import { activateLicense, deactivateLicense } from '@/infrastructure/licensing/license-service'
import { copyText } from '@/infrastructure/platform/clipboard'
import { useAppStore } from '@/stores/app-store'
import AppDialog from '@/components/AppDialog.vue'

const store = useAppStore()
const code = ref('')
const busy = ref(false)
const error = ref('')
const deactivateOpen = ref(false)
const statusText = computed(() => {
  if (store.license.kind === 'active') return '已激活，可使用全部功能'
  if (store.license.kind === 'expired') return `授权已过期：${store.license.expiresAt}`
  if (store.license.kind === 'invalid') return store.license.reason
  return '尚未激活'
})
const expiryLabel = computed(() => {
  if (store.license.kind !== 'active' || store.license.payload.e === undefined) return '永久有效'
  return `有效期至 ${new Date(store.license.payload.e).toLocaleDateString('zh-CN')}`
})
/** 当前已保存的授权码：激活后展示，方便用户换设备/浏览器时复制重输 */
const savedCode = computed(() => store.settings.licenseCode ?? '')

onMounted(async () => { await store.initialize() })

async function copyLicense(): Promise<void> {
  try {
    await copyText(savedCode.value)
    store.notify('授权码已复制', 'success')
  } catch (cause) {
    store.notify(cause instanceof Error ? cause.message : '复制失败，请长按授权码手动复制', 'error')
  }
}

async function activate(): Promise<void> {
  busy.value = true
  error.value = ''
  const status = await activateLicense(store.repository, code.value)
  if (status.kind === 'active') {
    await store.refreshLicense()
    // activateLicense 只写了持久层，这里同步内存 settings，否则本会话内「当前授权码」卡片读到旧值（空）
    store.settings = { ...store.settings, licenseCode: code.value.trim() }
    store.notify('授权激活成功', 'success')
    code.value = ''
  }
  else error.value = status.kind === 'invalid' ? status.reason : status.kind === 'expired' ? '授权码已过期，请联系作者续期' : '激活失败'
  busy.value = false
}

async function deactivate(): Promise<void> {
  await deactivateLicense(store.repository)
  await store.refreshLicense()
  // 同步清掉内存 settings 里的授权码，避免残留显示
  store.settings = { ...store.settings, licenseCode: undefined }
  deactivateOpen.value = false
  store.notify('已解绑授权码', 'success')
}
</script>

<template>
  <main class="page license-page">
    <section class="card status-card" :class="store.license.kind">
      <CheckCircle2 v-if="store.license.kind === 'active'" :size="36" aria-hidden="true" />
      <KeyRound v-else :size="36" aria-hidden="true" />
      <h2>{{ statusText }}</h2>
      <p v-if="store.license.kind === 'active'">{{ expiryLabel }}。激活后记账数据全程保存在本机。</p>
      <p v-else>激活需联网验证一次，之后可离线使用。</p>
    </section>

    <section v-if="store.license.kind !== 'active'" class="card license-card">
      <label for="license-code" class="field-label">输入授权码</label>
      <textarea id="license-code" v-model="code" class="field code-field" rows="4" autocomplete="off" placeholder="粘贴作者发给你的授权码" />
      <p v-if="error" class="field-error" role="alert">{{ error }}</p>
      <button class="button primary" type="button" :disabled="busy || !code.trim()" @click="activate"><KeyRound :size="19" />{{ busy ? '验证中…' : '激活授权码' }}</button>
      <p class="online-hint">激活需要联网，且一个授权码只能绑定一台设备。</p>
    </section>

    <section v-else class="card license-card">
      <h2>当前授权码</h2>
      <p>本授权码已绑定此设备。换设备或换浏览器需联系作者重发新码。</p>
      <code data-license-code>{{ savedCode }}</code>
      <button class="button secondary" type="button" @click="copyLicense"><Clipboard :size="19" />复制授权码</button>
    </section>

    <button v-if="store.license.kind === 'active'" class="button danger deactivate" type="button" @click="deactivateOpen = true"><LogOut :size="19" />解绑当前授权码</button>

    <p class="web-warning">更换浏览器或清除浏览器数据后授权状态会丢失；同一授权码只能激活一台设备，如需在其他设备使用请联系作者。</p>
  </main>

  <AppDialog :open="deactivateOpen" title="确认解绑授权码" @close="deactivateOpen = false">
    <p>解绑后将立即关闭新增、编辑和删除功能。已有账单与备份不会被删除，再次激活后可继续使用。</p>
    <template #actions>
      <button class="button secondary" type="button" @click="deactivateOpen = false">取消</button>
      <button class="button danger" type="button" @click="deactivate"><LogOut :size="18" />确认解绑</button>
    </template>
  </AppDialog>
</template>

<style scoped>
.license-page { display: grid; gap: 16px; }
.status-card, .license-card { display: grid; gap: 10px; padding: 18px 16px; }
.status-card { place-items: center; color: var(--color-text-secondary); text-align: center; }
.status-card.active { color: var(--color-income); }
.status-card h2 { margin: 0; color: var(--color-text); font-size: 18px; }
.status-card p, .license-card p { margin: 0; color: var(--color-text-secondary); }
.license-card h2 { margin: 0; font-size: 18px; }
.license-card code { padding: 12px; border-radius: 10px; background: var(--color-surface-muted); overflow-wrap: anywhere; color: var(--color-text); font-size: 13px; }
.code-field { min-height: 110px; resize: vertical; }
.online-hint { margin: 0; color: var(--color-text-secondary); font-size: 13px; }
.deactivate { width: 100%; }
.web-warning { margin: 0; color: var(--color-text-secondary); font-size: 13px; }
</style>
